          filePath.endsWith("app.css") ||
          ((filePath.includes("/ui/") || filePath.includes("\\ui\\")) &&
            ["html", "css", "scss"].includes(extension))
        ) {
          score += 40;
        } else if (
          ["css", "html", "scss"].includes(extension) ||
