import type { ExecutionPlan } from "../llm/executionPlan.js";
import type {
  AgentLoopResult,
  VerificationReason,
} from "../llm/agentLoop.js";

/**
 * Tur P2.1: multi-step plan orchestrator skeleton.
 *
 * Helpers only. The actual loop lives in runLlmPatchFlow's agent_loop branch
 * (gated on `ZONE_PLAN_ORCHESTRATION=1`). Pulled into its own module so the
 * pure functions (`buildStepTask`, `aggregateOrchestratorResults`,
 * `isPlanOrchestrationEnabled`) are independently testable without standing
 * up the whole patch flow.
 *
 * State transfer between steps, cancellation propagation, and per-step verdict
 * gating are deferred to P2.2 / P2.3 / P2.4 respectively.
 */

/**
 * Reads the env flag and verifies the plan is multi-step. Single-step or
 * empty plans always go single-pass even when the flag is set — there is no
 * value in orchestrating one step.
 */
export function isPlanOrchestrationEnabled(
  plan: ExecutionPlan | null | undefined,
  envValue: string | undefined
): boolean {
  const flag = String(envValue ?? "").trim().toLowerCase();
  const flagOn = flag === "1" || flag === "true";
  if (!flagOn) return false;
  if (!plan || !Array.isArray(plan.steps) || plan.steps.length < 2) return false;
  return true;
}

/**
 * Frames a single plan step within the user's original task so the agent
 * doesn't lose sight of the goal. Plain string concatenation — no LLM call.
 */
export function buildStepTask(
  originalTask: string,
  stepIdx: number,
  plan: ExecutionPlan
): string {
  const step = plan.steps[stepIdx];
  if (!step) return originalTask;
  const parts: string[] = [
    "ORIGINAL TASK:",
    String(originalTask ?? "").trim(),
    "",
    `CURRENT STEP (${stepIdx + 1} of ${plan.steps.length}):`,
    String(step.title ?? "").trim() || `Step ${stepIdx + 1}`,
  ];
  if (step.description && step.description.trim().length > 0) {
    parts.push("", String(step.description).trim());
  }
  if (Array.isArray(step.filesLikely) && step.filesLikely.length > 0) {
    parts.push("", `Files for this step: ${step.filesLikely.join(", ")}`);
  }
  parts.push(
    "",
    "Focus on completing ONLY this step. Other steps will be handled separately. Do not attempt the full task in this turn."
  );
  return parts.filter((line) => line !== undefined && line !== null).join("\n");
}

/**
 * Combines per-step AgentLoopResults into a single composite that matches
 * the shape downstream code in runLlmPatchFlow expects. P2.1 simplifications:
 *   - success: AND across all steps
 *   - filesModified: dedupe union
 *   - toolCallLog: concat in step order
 *   - summary: concat with step labels (last-step summary alone loses context)
 *   - error: join all step errors with `; `
 *   - patchValidatedByAgent: AND across all steps
 *   - verificationReason: last step's value (typically the verification step)
 *
 * Empty input returns a benign success result so callers can treat empty
 * runs uniformly.
 */
export function aggregateOrchestratorResults(
  results: AgentLoopResult[]
): AgentLoopResult {
  if (!Array.isArray(results) || results.length === 0) {
    return {
      success: true,
      summary: "",
      toolCallLog: [],
      filesModified: [],
      patchValidatedByAgent: false,
      verificationReason: "no_changes_made",
    };
  }

  const filesSet = new Set<string>();
  const toolLog: AgentLoopResult["toolCallLog"] = [];
  const summaries: string[] = [];
  const errors: string[] = [];
  let allSuccess = true;
  let allValidated = true;
  let lastVerificationReason: VerificationReason = "no_verification_attempted";

  for (let i = 0; i < results.length; i += 1) {
    const r = results[i]!;
    if (!r.success) allSuccess = false;
    if (!r.patchValidatedByAgent) allValidated = false;
    for (const f of r.filesModified ?? []) filesSet.add(f);
    if (Array.isArray(r.toolCallLog)) toolLog.push(...r.toolCallLog);
    if (r.summary && r.summary.trim().length > 0) {
      summaries.push(`[step ${i + 1}] ${r.summary.trim()}`);
    }
    if (r.error && r.error.trim().length > 0) {
      errors.push(`step ${i + 1}: ${r.error.trim()}`);
    }
    if (r.verificationReason) lastVerificationReason = r.verificationReason;
  }

  const composite: AgentLoopResult = {
    success: allSuccess,
    summary: summaries.join("\n\n"),
    toolCallLog: toolLog,
    filesModified: Array.from(filesSet),
    patchValidatedByAgent: allValidated,
    verificationReason: lastVerificationReason,
  };
  if (errors.length > 0) composite.error = errors.join("; ");
  return composite;
}

/**
 * Manual fixture test for checkWriteScope (Tur P2-scope plan-based guard).
 *
 * Build first (npm run build), then:
 *   node --experimental-strip-types src/tools/__tests__/runScopeGuardManual.ts
 *
 * Verifies that the write-scope guard returns null (allow) when there is no
 * plan / no filesLikely info / a matching path, and returns an actionable
 * error string when the file is outside the plan's filesLikely union.
 */
const { checkWriteScope } = await import(
  "../../../dist/tools/scopeGuard.js"
);

type AssertEntry = { name: string; pass: boolean; got: unknown };
const checks: AssertEntry[] = [];
function check(name: string, pass: boolean, got: unknown) {
  checks.push({ name, pass, got });
  console.log(`[assert] ${pass ? "PASS" : "FAIL"} ${name} :: ${JSON.stringify(got)}`);
}

const planTwoFiles = {
  objective: "demo",
  steps: [
    { title: "Step 1", description: "constants", filesLikely: ["lib/env.ts"] },
    { title: "Step 2", description: "utils", filesLikely: ["lib/utils.ts"] },
  ],
  riskHints: [],
  scopeSummary: "demo",
};

// 1. null plan → allow
{
  const got: string | null = checkWriteScope("any/file.ts", null);
  check("null plan → null", got === null, got);
}

// 2. undefined plan → allow
{
  const got: string | null = checkWriteScope("any/file.ts", undefined);
  check("undefined plan → null", got === null, got);
}

// 3. Plan with empty steps → allow
{
  const got: string | null = checkWriteScope(
    "lib/env.ts",
    { objective: "x", steps: [], riskHints: [], scopeSummary: "" } as never
  );
  check("empty steps → null", got === null, got);
}

// 4. Plan steps but every filesLikely is empty → allow (graceful fallback)
{
  const sparsePlan = {
    objective: "x",
    steps: [
      { title: "a", description: "", filesLikely: [] },
      { title: "b", description: "" }, // missing filesLikely entirely
    ],
    riskHints: [],
    scopeSummary: "",
  };
  const got: string | null = checkWriteScope("lib/env.ts", sparsePlan as never);
  check("empty filesLikely on all steps → null", got === null, got);
}

// 5. filePath in filesLikely → allow
{
  const got: string | null = checkWriteScope("lib/env.ts", planTwoFiles);
  check("path in filesLikely → null", got === null, got);
}

// 6. filePath NOT in filesLikely → block + error mentions plan scope
{
  const got: string | null = checkWriteScope(
    "components/AppProviders.tsx",
    planTwoFiles
  );
  const hasError = typeof got === "string" && got.length > 0;
  const mentionsScope = hasError && got.includes("lib/env.ts") && got.includes("lib/utils.ts");
  const mentionsTarget = hasError && got.includes("AppProviders.tsx");
  check("out-of-scope path → error string", hasError, got);
  check("error mentions plan scope", mentionsScope, got);
  check("error mentions blocked target path", mentionsTarget, got);
}

// 7. Path normalization: leading "./"
{
  const got: string | null = checkWriteScope("./lib/env.ts", planTwoFiles);
  check("./prefix matches lib/env.ts → null", got === null, got);
}

// 8. Path normalization: Windows backslashes
{
  const got: string | null = checkWriteScope("lib\\env.ts", planTwoFiles);
  check("backslashes match forward slashes → null", got === null, got);
}

// 9. Path normalization on the plan side too (filesLikely with ./)
{
  const planDotPrefix = {
    objective: "x",
    steps: [{ title: "s", description: "", filesLikely: ["./lib/env.ts"] }],
    riskHints: [],
    scopeSummary: "",
  };
  const got: string | null = checkWriteScope("lib/env.ts", planDotPrefix as never);
  check("plan filesLikely with ./ matches plain path → null", got === null, got);
}

// 10. Multi-step union: file in step 2's filesLikely passes
{
  const got: string | null = checkWriteScope("lib/utils.ts", planTwoFiles);
  check("path in step 2 filesLikely → null (union)", got === null, got);
}

// 11. Single step plan with single file — out-of-scope blocked
{
  const oneStepPlan = {
    objective: "x",
    steps: [{ title: "s", description: "", filesLikely: ["lib/env.ts"] }],
    riskHints: [],
    scopeSummary: "",
  };
  const got: string | null = checkWriteScope(
    "components/Header.tsx",
    oneStepPlan as never
  );
  check("single-step plan, out-of-scope → error", typeof got === "string" && got.length > 0, got);
}

// 12. Truncation hint when union has more than 5 paths
{
  const bigPlan = {
    objective: "x",
    steps: [
      {
        title: "s",
        description: "",
        filesLikely: [
          "a/1.ts",
          "a/2.ts",
          "a/3.ts",
          "a/4.ts",
          "a/5.ts",
          "a/6.ts",
          "a/7.ts",
        ],
      },
    ],
    riskHints: [],
    scopeSummary: "",
  };
  const got: string | null = checkWriteScope("z/other.ts", bigPlan as never);
  const truncated = typeof got === "string" && got.includes("(and 2 more)");
  check("more than 5 plan paths → 'and N more' suffix", truncated, got);
}

const passed = checks.filter((c) => c.pass).length;
const total = checks.length;
console.log(`\n[scope-guard-test] PASSED ${passed}/${total} assertions`);
if (passed !== total) process.exit(1);

