describe("U.1 — [zone-cache-usage] per-call emission", () => {
  it("emits [zone-cache-usage] when cache tokens are non-zero", async () => {
    let callCount = 0;
    mocks.createChatCompletion.mockImplementation(async () => {
      callCount += 1;
